import React, { useState, useEffect } from "react";
import Axios from "axios";
import "./ViewTasks.css"; 
import Navbar from "../components/navbar"; 
import Footer from "../components/footer"; 
import StudentSidebar from "../components/StudentSidebar"; 

const ViewTasks = () => {
  // State to manage the list of milestones
  const [milestones, setMilestones] = useState([]);

  // State for new task input fields
  const [newTask, setNewTask] = useState({
    title: "",
    status: "Pending",
    deadline: "",
  });

  const [user, setUser] = useState(null); // State to store current student info

  // Fetch current student information from local storage
  useEffect(() => {
    const currentUser = JSON.parse(localStorage.getItem('users'));
    if (currentUser) {
      setUser(currentUser); // Set user if available in local storage
    }
  }, []);

  // Function to fetch milestones
  useEffect(() => {
    const fetchMilestones = async () => {
      try {
        const response = await Axios.get("http://localhost:5000/api/milestone");
        setMilestones(response.data); // Store milestones data
      } catch (error) {
        console.error("Error fetching milestones:", error);
      }
    };

    fetchMilestones();
  }, []);

  // Function to handle adding a new task
  const handleAddTask = async (milestoneId) => {
    if (!newTask.title.trim()) {
      alert("Please enter a task title.");
      return;
    }

    const taskData = {
      milestoneId,
      title: newTask.title,
      status: newTask.status,
      uploadedBy: user ? user.studentName : "", // Use current student name as creator
    };

    try {
      // Sending task data to the backend API
      const response = await Axios.post("http://localhost:5000/api/task", taskData);
      console.log("Task added:", response.data);

      // Add the task to the specific milestone locally
      setMilestones((prevMilestones) =>
        prevMilestones.map((milestone) =>
          milestone._id === milestoneId
            ? {
                ...milestone,
                tasks: [...milestone.tasks, response.data],
              }
            : milestone
        )
      );
      // Clear task input fields
      setNewTask({ title: "", status: "Pending", deadline: "" });
    } catch (error) {
      console.error("Error adding task:", error.response ? error.response.data : error.message);
    }
  };

  // Function to update task status
  const handleUpdateTaskStatus = async (milestoneId, taskId, newStatus) => {
    try {
      // Call backend API to update task status
      const response = await Axios.patch(`http://localhost:5000/api/task/${taskId}`, { status: newStatus });
      console.log("Task status updated:", response.data);

      // Update the task locally in state
      setMilestones((prevMilestones) =>
        prevMilestones.map((milestone) =>
          milestone._id === milestoneId
            ? {
                ...milestone,
                tasks: milestone.tasks.map((task) =>
                  task._id === taskId ? { ...task, status: newStatus } : task
                ),
              }
            : milestone
        )
      );
    } catch (error) {
      console.error("Error updating task status:", error);
    }
  };

  return (
    <div className="tasks-container">
      <Navbar />
      <div className="content-wrapper">
        <StudentSidebar />
        <div className="main-content">
          <h1 className="tasks-title">Manage Milestones and Tasks</h1>

          {/* List of Milestones with Tasks */}
          <div className="milestone-list">
            {milestones.map((milestone) => (
              <div key={milestone._id} className="milestone-item">
                <h2>{milestone.title}</h2>
                <p>Due Date: {new Date(milestone.dueDate).toLocaleDateString()}</p>

                {/* Input Fields for Adding a Task */}
                <div className="task-section">
                  <input 
                    type="text" 
                    value={newTask.title} 
                    onChange={(e) => setNewTask({ ...newTask, title: e.target.value })} 
                    placeholder="Task title" 
                  />
                  <button className="task-button" onClick={() => handleAddTask(milestone._id)}>
                    Add Task
                  </button>

                  {/* Table of Tasks Under the Milestone */}
                  <div className="tasks-table">
                    <table>
                      <thead>
                        <tr>
                          <th>Task</th>
                          <th>Status</th>
                          <th>Created By</th>
                          <th>Actions</th>
                        </tr>
                      </thead>
                      <tbody>
                        {milestone.tasks && milestone.tasks.map((task) => (
                          <tr key={task._id}>
                            <td>{task.title}</td>
                            <td>{task.status}</td>
                            <td>{task.uploadedBy}</td>
                            <td>
                              <button 
                                className="mark-completed-button"
                                onClick={() => handleUpdateTaskStatus(milestone._id, task._id, "Completed")}
                              >
                                Mark as Completed
                              </button>
                            </td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                  </div>
                </div>
              </div>
            ))}
          </div>
        </div>
      </div>
      <Footer />
    </div>
  );
};

export default ViewTasks;
